50	        _listDetector = new LeaguePanelDetector(options, loggerFactory.CreateLogger<LeaguePanelDetector>());
51	
52	        var effectiveBackend = ResolveEffectiveOcrBackend(_options.CurrentValue.OcrBackend);
53	        if (!string.Equals(effectiveBackend, _options.CurrentValue.OcrBackend, StringComparison.OrdinalIgnoreCase))
54	            _logger.LogWarning("OCR backend falling back from {Configured} to {Effective} (Windows build too old).",
55	                _options.CurrentValue.OcrBackend, effectiveBackend);
56	        else
57	            _logger.LogInformation("OCR backend: {Backend}", effectiveBackend);
58	        var poe2Lang = Poe2ConfigFile.Language;
59	        _detectedLanguage = poe2Lang is not null && ItemNameTranslator.IsLanguageSupported(poe2Lang) ? poe2Lang : null;
60	        _logger.LogDebug("PoE2 game language detected: {Detected} (configured default: {Configured})",
61	            poe2Lang ?? "(none)", _options.CurrentValue.Language);
62	        _metrics.OcrBackend = effectiveBackend;
63	        _metrics.Language = _detectedLanguage ?? _options.CurrentValue.Language;
64	        _metrics.OcrEngineMode = _options.CurrentValue.OcrEngineMode.ToString(System.Globalization.CultureInfo.InvariantCulture);
65	
66	        // Seed debug-image tracking fields so that the first OnChange callback
67	        // can detect actual changes vs the initial values.
68	        var initial = _options.CurrentValue;
69	        _lastDebugSaveEnabled = initial.SaveDebugImages;
70	        _lastDebugImageInterval = initial.DebugImageIntervalSeconds;
71	        _lastDebugImageDirectory = initial.DebugImageDirectory;
72	
73	        // Listen for PoE2 config file changes (language, brightness, etc.)
74	        Poe2ConfigFile.ConfigChanged += OnPoe2ConfigChanged;
75	
76	        _optionsSubscription = _options.OnChange((updated, __) =>
77	        {
78	            lock (_ocrGate)
79	            {
80	                if (_disposed) return;
81	                var effective = ResolveEffectiveOcrBackend(updated.OcrBackend);
82	                try
83	                {
84	                    // Only keep Tesseract engine loaded when Tesseract is the selected backend
85	                    if (!string.Equals(effective, "windows", StringComparison.OrdinalIgnoreCase))
86	                        _engineManager.GetEngine(updated, ResolveEffectiveLanguage(updated));
87	                    else
88	                        _engineManager.DisposeEngine();
89	                }
90	                catch (Exception ex)
91	                {
92	                    _logger.LogError(ex, "Failed to apply OCR backend settings change: {Context}", ErrorContext.FromException(ex));
93	                }
94	
95	                if (!string.Equals(_activeOcrBackend, effective, StringComparison.OrdinalIgnoreCase))
96	                {
97	                    var previous = _activeOcrBackend;
98	                    _activeOcrBackend = null; // force engine re-init on next cycle
99	                    _lastOcrText = "";        // force non-cached snapshot
100	                    _metrics.OcrBackend = effective; // update so dashboard toggles slot breakdown
101	                    if (previous is not null) // only log actual switches, not initial load
102	                        _logger.LogInformation("OCR backend changed to: {Backend}", effective);
103	                }
104	                // Always invalidate the frame-differencing cache when any OCR option changes
105	                // (tolerance, thresholds, binarization, etc.) so the new value takes effect
106	                // on the next cycle rather than returning stale cached text.
107	                _lastOcrText = "";
108	                _lastOcrOptions = null;
109	                _runContext = _runContext with { FrameHash = 0 };
110	
111	                // When debug-image settings change (SaveDebugImages, interval, directory),
112	                // reset the debug capture gate so the change takes effect immediately.
113	                if (updated.SaveDebugImages != _lastDebugSaveEnabled ||
114	                    updated.DebugImageIntervalSeconds != _lastDebugImageInterval ||
115	                    !string.Equals(updated.DebugImageDirectory, _lastDebugImageDirectory, StringComparison.Ordinal))
116	                {
117	                    _lastDebugImageSavedAtUtc = DateTimeOffset.MinValue;
118	                    _lastDebugFrameHash = 0;
119	                    _lastDebugSaveEnabled = updated.SaveDebugImages;
120	                    _lastDebugImageInterval = updated.DebugImageIntervalSeconds;
121	                    _lastDebugImageDirectory = updated.DebugImageDirectory;
122	                }
123	            }
124	        });
125	    }
