216	    private LeagueWindowSnapshot ReadSnapshotCore()
217	    {
218	        var capturedAt = DateTimeOffset.UtcNow;
219	
220	
221	        if (_logState.HasFlag(OcrLogState.TesseractUnavailable))
222	        {
223	            return CreateEmptySnapshot(capturedAt);
224	        }
225	
226	        var currentLang = ResolveEffectiveLanguage(_options.CurrentValue);
227	        if (!ItemNameTranslator.IsLanguageSupported(currentLang))
228	        {
229	            if (!_logState.HasFlag(OcrLogState.UnsupportedLanguage))
230	            {
231	                _logState |= OcrLogState.UnsupportedLanguage;
232	                _logger.LogWarning("OCR disabled — language '{Lang}' is not supported", currentLang);
233	            }
234	            return CreateEmptySnapshot(capturedAt);
235	        }
236	
237	        try
238	        {
239	            var rawText = CaptureAndRecognize(out var attemptedRecognition, out var fromCache);
240	            if (!attemptedRecognition)
241	            {
242	                _lastSnapshot = null;
243	                return CreateEmptySnapshot(capturedAt);
244	            }
245	
246	            if (fromCache && _lastSnapshot is not null)
247	                return _lastSnapshot;
248	
249	            if (_appOptions.CurrentValue.LogLevel <= LogLevel.Debug && !_logState.HasFlag(OcrLogState.TesseractExecutionConfirmed))
250	            {
251	                _logState |= OcrLogState.TesseractExecutionConfirmed;
252	                _logger.LogDebug("OCR engine confirmed: tesseract executed successfully.");
253	            }
254	
255	            var (lines, matchedYPositions) = _lastRowTexts is not null
256	                ? OcrTextPostProcessor.ExtractFromRowTexts(
257	                    _lastRowTexts, _runContext.RowYPositions, _detectedLanguage)
258	                : OcrTextPostProcessor.ExtractWithYPositions(
259	                    rawText, _runContext.RowYPositions, _detectedLanguage);
260	
261	            // Draw purple boxes matching each row's individual content bounds.
262	            // Clear stale regions from previous cycles first so old positions don't
263	            // accumulate (they were never cleared, causing duplicate offset boxes).
264	            _retryRegions.Clear();
265	            _rejectedRegions.Clear();
266	            var validRowMask = new bool[_lastOcrRowYPositions.Length > 0 ? _lastOcrRowYPositions.Length : 0];
267	            if (_lastOcrRowYPositions.Length > 0 && _lastPreprocessedBitmap is not null)
268	            {
269	                var pbmp = _lastPreprocessedBitmap;
270	                var rect = new Rectangle(0, 0, pbmp.Width, pbmp.Height);
271	                // Only keep rows whose content extends to the rightmost 15% of
272	                // the capture region — narrow clusters near the left are rune
273	                // icons, not real text.
274	                var rightEdgeThreshold = (int)(pbmp.Width * 0.85);
275	                var data = pbmp.LockBits(rect, ImageLockMode.ReadOnly, PixelFormat.Format24bppRgb);
276	                try
277	                {
278	                    var stride = data.Stride;
279	                    var bytes = new byte[Math.Abs(stride) * pbmp.Height];
280	                    Marshal.Copy(data.Scan0, bytes, 0, bytes.Length);
281	
282	                    // Text column starts at PanelLeftFraction — don't scan left of it
283	                    var textColStart = (int)(pbmp.Width * _options.CurrentValue.PanelLeftFraction);
284	
285	                    for (var i = 0; i < _lastOcrRowYPositions.Length; i++)
286	                    {
287	                        var y = _lastOcrRowYPositions[i];
288	                        var h = i < _lastOcrRowHeights.Length ? _lastOcrRowHeights[i] : 16;
289	                        var yEnd = Math.Min(y + h, pbmp.Height);
290	
291	                        // Find leftmost and rightmost dark pixel within this row band,
292	                        // but only within the text column (right of the yellow dashed line)
293	                        var minX = pbmp.Width;
294	                        var maxX = 0;
295	                        for (var ry = y; ry < yEnd; ry++)
296	                        {
297	                            var rowOffset = ry * stride;
298	                            for (var rx = textColStart; rx < pbmp.Width; rx++)
299	                            {
300	                                if (bytes[rowOffset + (rx * 3)] < 128)
301	                                {
302	                                    if (rx < minX) minX = rx;
303	                                    if (rx > maxX) maxX = rx;
304	                                }
305	                            }
306	                        }
307	
308	                        if (maxX >= minX)
309	                        {
310	                            const int margin = 4;
311	                            var boxX = Math.Max(0, minX - margin);
312	                            var boxW = Math.Min(pbmp.Width - boxX, maxX - minX + (margin * 2));
313	                            var right = boxX + boxW;
314	                            var box = new Rectangle(boxX, y, boxW, h);
315	
316	                            // Only keep rows whose content reaches the rightmost
317	                            // portion of the capture region — real text spans most
318	                            // of the width, rune icons don't.
319	                            if (right >= rightEdgeThreshold)
320	                            {
321	                                validRowMask[i] = true;
322	                                _retryRegions.Add(box);
323	                            }
324	                            else
325	                            {
326	                                _rejectedRegions.Add(box);
327	                                if (_logger.IsEnabled(LogLevel.Trace))
328	                                    _logger.LogTrace(
329	                                        "Row {Row} @Y={Y} rejected: right edge {Right} < threshold {Threshold} (cluster too narrow for text)",
330	                                        i, y, right, rightEdgeThreshold);
331	                            }
332	                        }
333	                        else
334	                        {
335	                            // Fallback: use full width (always valid)
336	                            validRowMask[i] = true;
337	                            _retryRegions.Add(new Rectangle(0, y, pbmp.Width, h));
338	                        }
339	                    }
340	                }
341	                finally
342	                {
343	                    pbmp.UnlockBits(data);
344	                }
345	
346	                if (_logger.IsEnabled(LogLevel.Debug) && _rejectedRegions.Count > 0)
347	                {
348	                    _logger.LogDebug(
349	                        "Row filtering: {Kept} kept, {Rejected} rejected (right edge < {Threshold}px)",
350	                        _retryRegions.Count, _rejectedRegions.Count, rightEdgeThreshold);
351	                }
352	
353	                // Filter lines/matchedYPositions to match the kept rows.
354	                // Since ExtractFromRowTexts now returns correctly-paired data
355	                // (each line keeps its original Y position), we map each line
356	                // back to its original row index so the right-edge rejection
357	                // mask (indexed by original row index) is applied correctly.
358	                if (validRowMask.Length > 0)
359	                {
360	                    var keptLines = new List<string>(lines.Length);
361	                    var keptY = new List<int>(matchedYPositions.Length);
362	                    for (var i = 0; i < lines.Length; i++)
363	                    {
364	                        var y = matchedYPositions[i];
365	                        var origIndex = Array.IndexOf(_lastOcrRowYPositions, y);
366	                        if (origIndex >= 0 && origIndex < validRowMask.Length && validRowMask[origIndex])
367	                        {
368	                            keptLines.Add(lines[i]);
369	                            keptY.Add(matchedYPositions[i]);
370	                        }
371	                    }
372	                    lines = [.. keptLines];
373	                    matchedYPositions = [.. keptY];
374	                }
375	
376	                _lastCropBounds = null; // hide green content-bounds box
377	            }
378	
379	            if (_appOptions.CurrentValue.LogLevel <= LogLevel.Debug)
380	            {
381	                var items = lines.Length == 0
382	                    ? "<none>"
383	                    : string.Join(" | ", BuildItemDebugStrings(lines, matchedYPositions));
384	                _logger.LogDebug("OCR detected {Count} items: {Items}", lines.Length, items);
385	            }
386	
387	            _dashboard.SetStatus("Scanning league panel", "green");
388	
389	            _lastSnapshot = new LeagueWindowSnapshot(lines, capturedAt, matchedYPositions, InterfaceDetected: true, CaptureMethod: ResolveStatusLine(), CropBounds: _lastCropBounds, RetryRegions: _retryRegions.Count > 0 ? [.. _retryRegions] : null, RejectedRegions: _rejectedRegions.Count > 0 ? [.. _rejectedRegions] : null);
390	            _metrics.ItemsDetected = lines.Length;
391	            _metrics.InterfaceDetected = true;
392	            return _lastSnapshot;
393	        }
394	        catch (System.ComponentModel.Win32Exception ex) when (ex.NativeErrorCode == 2)
395	        {
396	            _logState |= OcrLogState.TesseractUnavailable;
397	            _logger.LogWarning(
398	                "OCR disabled: Tesseract not found. Install from https://github.com/UB-Mannheim/tesseract/wiki then restart RuneshapePriceChecker.");
399	            return new LeagueWindowSnapshot([], capturedAt, InterfaceDetected: _lastInterfaceDetected);
400	        }
401	        catch (Exception ex) when (ex is FileNotFoundException or TypeLoadException or DllNotFoundException)
402	        {
403	            _logState |= OcrLogState.TesseractUnavailable;
404	            _logger.LogWarning(
405	                "OCR disabled: {Reason} Install Tesseract from https://github.com/UB-Mannheim/tesseract/wiki then restart RuneshapePriceChecker.",
406	                ex.Message);
407	            return new LeagueWindowSnapshot([], capturedAt, InterfaceDetected: _lastInterfaceDetected);
408	        }
409	        catch (Exception ex)
410	        {
411	            _logger.LogError(ex, "OCR pipeline threw unhandled exception: {Context} (lang={Lang} backend={Backend} capture={Method})",
412	                ErrorContext.FromException(ex),
413	                _detectedLanguage ?? _options.CurrentValue.Language, _activeOcrBackend, _runContext.CaptureMethod);
414	            return new LeagueWindowSnapshot([], capturedAt, InterfaceDetected: false);
415	        }
416	    }
417	
418	    private string CaptureAndRecognize(out bool attemptedRecognition, out bool fromCache)
419	    {
420	        attemptedRecognition = false;
421	        fromCache = false;
422	        _perf.ResetCycleSlotMs();
423	        var t0 = OcrPerfTiming.RecordStart(OcrPerfTiming.Slot.Total);
424	        var options = _options.CurrentValue;
425	        if (_detectedLanguage is not null)
426	        {
427	            if (ItemNameTranslator.IsLanguageSupported(_detectedLanguage))
428	            {
429	                if (!string.Equals(options.Language, _detectedLanguage, StringComparison.OrdinalIgnoreCase))
430	                {
431	                    _logger.LogInformation(
432	                        "OCR language mismatch: configured={Configured}, detected={Detected}. Using detected language.",
433	                        options.Language, _detectedLanguage);
434	                }
435	                // The monitored options instance is immutable for this OCR cycle.
436	            }
437	            else
438	            {
439	                _logger.LogDebug(
440	                    "OCR language: detected='{Detected}' is not supported — keeping configured default '{Lang}'.",
441	                    _detectedLanguage, options.Language);
442	            }
443	        }
444	        else
445	        {
446	            _logger.LogTrace("OCR language: using configured default '{Lang}' (no detected language override).", options.Language);
447	        }
448	        var effectiveLanguage = ResolveEffectiveLanguage(options);
449	        if (options.SaveDebugImages)
450	            EnsureDebugImageDirectoryExists(options);
451	
452	        // Use the cached foreground state from Poe2WindowResolutionService
453	        // (updated every 1 second) instead of an extra per-cycle Win32 call.
454	        if (!_windowResolutionProvider.IsPoe2WindowForeground)
455	        {
456	            _lastInterfaceDetected = false;
457	            if (!_logState.HasFlag(OcrLogState.ForegroundWindowLogged))
458	            {
459	                _logState |= OcrLogState.ForegroundWindowLogged;
460	                _logger.LogDebug("OCR paused: waiting for Path of Exile 2 to be the active foreground window.");
461	            }
462	
463	            _dashboard.SetStatus("Waiting for PoE2 window", "amber");
464	            _metrics.IsPoe2Foreground = false;
465	            _metrics.InterfaceDetected = false;
466	            return string.Empty;
467	        }
468	
469	        if (_logState.HasFlag(OcrLogState.ForegroundWindowLogged))
470	        {
471	            _logState &= ~OcrLogState.ForegroundWindowLogged;
472	            _logger.LogDebug("PoE2 foreground confirmed; OCR scanning is active.");
473	        }
474	
475	        if (_windowResolutionProvider.CurrentWindowCaptureContext is null)
476	        {
477	            if (_appOptions.CurrentValue.LogLevel <= LogLevel.Debug && !_logState.HasFlag(OcrLogState.WindowContextLogged))
478	            {
479	                _logState |= OcrLogState.WindowContextLogged;
480	                _logger.LogDebug("OCR warm-up: waiting for PoE2 window capture context before first scan.");
481	            }
482	
483	            return string.Empty;
484	        }
485	
486	        _logState &= ~OcrLogState.WindowContextLogged;
487	
488	        var region = ResolveCaptureRegion();
489	        if (region is null)
490	        {
491	            _metrics.InterfaceDetected = false;
492	            return string.Empty;
493	        }
494	        ValidateRegion(region);
495	        _metrics.RegionInfo = $"{region.Width}x{region.Height}";
496	
497	        // Pre-capture panel check: capture only the scan rectangle area (~40K px)
498	        // instead of the full region (266K px) to check if the panel is still closed.
499	        // Uses a direct CopyFromScreen to bypass the capture strategy's fallback chain.
500	        var opts = _options.CurrentValue;
501	        var scanRect = new OcrCaptureRegion(
502	            region.X + (int)(region.Width * opts.PanelLeftFraction),
503	            region.Y,
504	            (int)(region.Width * (opts.PanelRightFraction - opts.PanelLeftFraction)),
505	            (int)(region.Height * opts.PanelTopRowFraction));
506	        using (var preCapturePerf = _perf.Measure(OcrPerfTiming.Slot.AnchorCheck))
507	        {
508	            using var directScanBitmap = CaptureDesktopRegionDirect(scanRect, _logger);
509	            CaptureResult? fallbackScanCapture = null;
510	            try
511	            {
512	                var scanBitmap = directScanBitmap;
513	                if (scanBitmap is null)
514	                {
515	                    fallbackScanCapture = _captureStrategy.Capture(
516	                        scanRect,
517	                        _windowResolutionProvider.CurrentWindowCaptureContext,
518	                        options);
519	                    scanBitmap = fallbackScanCapture?.Bitmap;
520	                    if (scanBitmap is not null)
521	                        _logger.LogWarning("Direct anchor capture failed; using the configured capture strategy for the anchor check.");
522	                }
523	
524	                _logger.LogTrace("GDI: anchor capture result={HasBitmap}", scanBitmap is not null);
525	                if (scanBitmap is null || !TryDetectPanelOpen(scanBitmap, options, region))
526	                {
527	                    _metrics.AnchorCheckFails++;
528	                    _metrics.InterfaceDetected = false;
529	                    return string.Empty;
530	                }
531	                _metrics.AnchorCheckPasses++;
532	            }
533	            finally
534	            {
535	                fallbackScanCapture?.Bitmap.Dispose();
536	            }
537	        }
538	
539	        var configuredMode = options.CaptureMode?.ToLowerInvariant() ?? "printwindow";
540	        CaptureResult? captureResult;
541	        string captureMethod;
542	        using (_perf.Measure(OcrPerfTiming.Slot.Capture))
543	        {
544	            captureResult = _captureStrategy.Capture(region, _windowResolutionProvider.CurrentWindowCaptureContext, options);
545	        }
546	
547	        if (captureResult is null)
548	        {
549	            _ = _metrics.FailedCaptureModes.TryAdd(configuredMode, 0);
550	            _metrics.InterfaceDetected = false;
551	            _dashboard.SetStatus("Screen capture unavailable", "amber");
552	            _logger.LogWarning("OCR capture failed for configured mode {Mode}; waiting for the next capture cycle.", configuredMode);
553	            return string.Empty;
554	        }
555	
556	        captureMethod = captureResult.Method;
557	
558	        // Track capture mode failures: if user selected a specific mode but we got a different one, it failed.
559	        // If they match, clear any prior failure so transient issues don't permanently disable a mode.
560	        var actualPrefix = captureMethod switch
561	        {
562	            string m when m.Contains("bitblt") => "bitblt",
563	            string m when m.Contains("printwindow") => "printwindow",
564	            _ => "desktop"
565	        };
566	        if (!string.Equals(configuredMode, actualPrefix, StringComparison.OrdinalIgnoreCase))
567	            _ = _metrics.FailedCaptureModes.TryAdd(configuredMode, 0);
568	        else
569	            _ = _metrics.FailedCaptureModes.TryRemove(configuredMode, out _);
570	        using var capturedBitmap = captureResult.Bitmap;
571	
572	        // Keep a clone for per-row filtering until the next cycle.
573	        _lastPreprocessedBitmap?.Dispose();
574	        _lastPreprocessedBitmap = null; // Will be set after preprocessing below
575	
576	        if (!string.Equals(_runContext.CaptureMethod, captureMethod, StringComparison.OrdinalIgnoreCase))
577	        {
578	            _logger.LogTrace("OCR capture source active: {CaptureMethod}.", captureMethod);
579	        }
580	
581	        _runContext = _runContext with { CaptureMethod = captureMethod };
582	
583	        // Panel was already confirmed open by the pre-capture check above.
584	        _metrics.InterfaceDetected = true;
585	
586	        using (_perf.Measure(OcrPerfTiming.Slot.FrameHash))
587	        {
588	            if (TrySkipOcrViaFrameDifferencing(capturedBitmap, options))
589	            {
590	                attemptedRecognition = true;
591	                fromCache = true;
592	                _runContext = _runContext with { RowYPositions = _lastOcrRowYPositions };
593	                _perf.RecordEnd(OcrPerfTiming.Slot.Total, t0);
594	                _perf.RecordEnd(OcrPerfTiming.Slot.CacheHit, t0);
595	                var totalMs = Stopwatch.GetElapsedTime(t0).TotalMilliseconds;
596	                _metrics.RecordCycle(totalMs, fromCache: true, isFullOcr: false);
597	                _metrics.CaptureMethod = _runContext.CaptureMethod;
598	                _metrics.IsPoe2Foreground = true;
599	                _metrics.InterfaceDetected = true;
600	                // Record per-cycle slot data so the breakdown stays in sync with Avg Duration
601	                var cacheCycleSlots = _perf.GetCycleSlotMs();
602	                for (var s = 0; s < cacheCycleSlots.Length; s++)
603	                    _metrics.RecordSlotDuration(s, cacheCycleSlots[s]);
604	                TryLogPerfMetrics(options);
605	                return _lastOcrText;
606	            }
607	        }
608	
609	        var debugContext = options.SaveDebugImages
610	            ? TryStartDebugCapture(capturedBitmap, region, captureMethod)
611	            : null;
612	
613	        attemptedRecognition = true;
614	        Bitmap preprocessed = null!;
615	        Bitmap? masked = null;
616	        try
617	        {
618	            using (_perf.Measure(OcrPerfTiming.Slot.KeepBlack))
619	                masked = OcrImagePreprocessor.KeepBlackAndNeighbors(capturedBitmap, _logger);
620	            using (_perf.Measure(OcrPerfTiming.Slot.Preprocess))
621	                preprocessed = OcrImagePreprocessor.PreprocessForOcr(masked, options, _logger);
622	            _logger.LogTrace("GDI: disposing old preprocessed bitmap");
623	            _lastPreprocessedBitmap?.Dispose();
624	            _logger.LogTrace("GDI: cloning preprocessed bitmap");
625	            _lastPreprocessedBitmap = new Bitmap(preprocessed);
626	            _logger.LogTrace("GDI: preprocessed clone OK");
627	
628	            // Extract pixel bytes ONCE and pass to downstream methods so they don't
629	            // need to call LockBits (which triggers MetaDataGetDispenser COM interop
630	            // and crashes). FindContentBounds and DetectRowPositions each called
631	            // LockBits independently before — consolidate to a single extraction.
632	            _logger.LogTrace("GDI: extract bytes for content bounds / row detection");
633	            var srcRect = new Rectangle(0, 0, preprocessed.Width, preprocessed.Height);
634	            var srcData = preprocessed.LockBits(srcRect, ImageLockMode.ReadOnly, PixelFormat.Format24bppRgb);
635	            int stride;
636	            byte[] pixelBytes;
637	            try
638	            {
639	                stride = srcData.Stride;
640	                var pixelLen = Math.Abs(stride) * preprocessed.Height;
641	                pixelBytes = new byte[pixelLen];
642	                Marshal.Copy(srcData.Scan0, pixelBytes, 0, pixelLen);
643	            }
644	            finally
645	            {
646	                preprocessed.UnlockBits(srcData);
647	            }
648	            _logger.LogTrace("GDI: bytes extracted OK");
649	
650	            Rectangle? crop;
651	            using (_perf.Measure(OcrPerfTiming.Slot.PostProcess))
652	                crop = OcrImagePreprocessor.FindContentBounds(pixelBytes, preprocessed.Width, preprocessed.Height, stride);
653	
654	            // Shift the left edge of the scan region from the icon column to the
655	            // panel text column, so rune icons don't inflate row widths and confuse
656	            // the row detection.  The left yellow dashed line in the debug overlay marks
657	            // this boundary.
658	            if (crop.HasValue && preprocessed.Width > 0)
659	            {
660	                var textColX = (int)(preprocessed.Width * options.PanelLeftFraction);
661	                var newX = Math.Max(crop.Value.X, textColX);
662	                crop = new Rectangle(newX, crop.Value.Y,
663	                    Math.Max(1, crop.Value.Right - newX), crop.Value.Height);
664	            }
665	
666	            var debugDir = debugContext?.DirectoryPath;
667	            if (debugDir is not null)
668	            {
669	                OcrImagePreprocessor.SavePng(capturedBitmap, Path.Combine(debugDir, "1 Raw.png"));
670	                if (masked is not null)
671	                    OcrImagePreprocessor.SavePng(masked, Path.Combine(debugDir, "2 Mask.png"));
672	                OcrImagePreprocessor.SavePng(preprocessed, Path.Combine(debugDir, "3 Preprocessed.png"));
673	                if (crop.HasValue)
674	                {
675	                    using var croppedDbg = OcrImagePreprocessor.CropBitmap(preprocessed, crop.Value);
676	                    OcrImagePreprocessor.SavePng(croppedDbg, Path.Combine(debugDir, "4 Cropped.png"));
677	                }
678	            }
679	
680	            _logger.LogTrace("GDI: about to call DetectRowPositions");
681	            int[] rowYs, rowHeights;
682	            using (_perf.Measure(OcrPerfTiming.Slot.PostProcess))
683	                (rowYs, rowHeights) = OcrPipeline.DetectRowPositions(pixelBytes, preprocessed.Width, preprocessed.Height, stride, crop);
684	            _logger.LogTrace("GDI: DetectRowPositions done");
685	            _lastOcrRowHeights = rowHeights;
686	            _lastOcrRowYPositions = rowYs;
687	            _lastCropBounds = crop;
688	            _runContext = _runContext with { RowYPositions = rowYs };
689	
690	            if (rowYs.Length == 0)
691	            {
692	                _lastOcrText = string.Empty;
693	                _lastOcrOptions = options;
694	                _lastRowTexts = [];
695	            }
696	            else
697	            {
698	                var rowTexts = new string[rowYs.Length];
699	
700	                if (IsWindowsOcrEnabled(options))
701	                {
702	                    EnsureWindowsOcrEngine();
703	                    using (_perf.Measure(OcrPerfTiming.Slot.Recognize))
704	                    {
705	                        for (var i = 0; i < rowYs.Length; i++)
706	                        {
707	                            var rowBitmap = OcrPipeline.PrepareRowBitmap(preprocessed, crop, rowYs[i], rowHeights[i]);
708	                            try
709	                            {
710	                                var rawText = _windowsOcrEngine!.Recognize(rowBitmap, out _, 3, null);
711	                                var lines = OcrImagePreprocessor.SplitAndTrim(rawText);
712	                                var cleaned = lines.Length > 0
713	                                    ? (OcrTextPostProcessor.ExtractLikelyItemNames(lines[0], _detectedLanguage) is { Count: > 0 } cl ? cl[0] : lines[0])
714	                                    : string.Empty;
715	                                _logger.LogTrace("OCR: row {Row} raw='{Raw}' cleaned='{Clean}' lang={Lang}", i, rawText, cleaned, _detectedLanguage);
716	                                rowTexts[i] = cleaned;
717	                            }
718	                            finally
719	                            {
720	                                rowBitmap.Dispose();
721	                            }
722	
723	                            if (debugDir is not null)
724	                                OcrPipeline.SaveRowDebugImage(preprocessed, crop, rowYs[i], rowHeights[i], i, debugDir);
725	                        }
726	                    }
727	                }
728	                else
729	                {
730	                    _activeOcrBackend = "tesseract";
731	                    _metrics.OcrBackend = "tesseract";
732	                    var engine = _engineManager.GetEngine(options, effectiveLanguage)!;
733	                    engine.SetPageSegMode(7); // PSM_SINGLE_LINE
734	
735	                    using (_perf.Measure(OcrPerfTiming.Slot.Recognize))
736	                    {
737	                        for (var i = 0; i < rowYs.Length; i++)
738	                        {
739	                            string? text;
740	                            try
741	                            {
742	                                var rowBitmap = OcrPipeline.PrepareRowBitmap(preprocessed, crop, rowYs[i], rowHeights[i]);
743	                                try
744	                                {
745	                                    text = engine.RecognizeSingleLine(rowBitmap);
746	                                }
747	                                finally
748	                                {
749	                                    rowBitmap.Dispose();
750	                                }
751	                            }
752	                            catch (Exception ex)
753	                            {
754	                                _logger.LogError(ex, "Per-row Tesseract recognition failed for row {Row}/{Total}: {Context}", i + 1, rowYs.Length, ErrorContext.FromException(ex));
755	                                text = null;
756	                            }
757	                            var tessCleaned = text ?? string.Empty;
758	                            _logger.LogTrace("OCR: row {Row} raw='{Raw}' cleaned='{Clean}' lang={Lang} backend=tesseract", i, text, tessCleaned, _detectedLanguage);
759	                            rowTexts[i] = tessCleaned;
760	
761	                            if (debugDir is not null)
762	                                OcrPipeline.SaveRowDebugImage(preprocessed, crop, rowYs[i], rowHeights[i], i, debugDir);
763	                        }
764	                    }
765	                }
766	
767	                if (debugDir is not null)
768	                    OcrPipeline.SaveRowOverlayDebugImage(preprocessed, crop, rowYs, rowHeights, debugDir);
769	
770	                string joined;
771	                using (_perf.Measure(OcrPerfTiming.Slot.PostProcess))
772	                    joined = string.Join(Environment.NewLine, rowTexts);
773	                _lastOcrText = joined;
774	                _lastOcrOptions = options;
775	                _lastRowTexts = rowTexts;
776	            }
777	
778	            _perf.RecordEnd(OcrPerfTiming.Slot.Total, t0);
779	            var fullOcrMs = Stopwatch.GetElapsedTime(t0).TotalMilliseconds;
780	            _metrics.RecordCycle(fullOcrMs, fromCache: false, isFullOcr: true);
781	            _metrics.CaptureMethod = _runContext.CaptureMethod;
782	            _metrics.IsPoe2Foreground = true;
783	            _metrics.InterfaceDetected = true;
784	            var cycleSlots = _perf.GetCycleSlotMs();
785	            for (var s = 0; s < cycleSlots.Length; s++)
786	                _metrics.RecordSlotDuration(s, cycleSlots[s]);
787	            TryLogPerfMetrics(options);
788	
789	            _retryRegions.Clear();
790	            _rejectedRegions.Clear();
791	            return _lastOcrText;
792	        }
793	        finally
794	        {
795	            masked?.Dispose();
796	            preprocessed?.Dispose();
797	        }
798	    }
