853	    private void EnsureWindowsOcrEngine()
854	    {
855	        var lang = ResolveEffectiveLanguage(_options.CurrentValue);
856	        var backend = ResolveEffectiveOcrBackend(_options.CurrentValue.OcrBackend);
857	        if (_activeOcrBackend == backend && string.Equals(_activeOcrLanguage, lang, StringComparison.OrdinalIgnoreCase) && _windowsOcrEngine is not null)
858	        {
859	            // Periodically retry engine creation (every ~15s) so that if the user
860	            // installed the language pack after we created a fallback engine, we
861	            // pick it up on the next retry without requiring an app restart.
862	            if (!_windowsOcrEngine.IsExactLanguageMatch && (_lastWindowsOcrRetryUtc is null ||
863	                (DateTime.UtcNow - _lastWindowsOcrRetryUtc.Value).TotalSeconds >= 15)
864	            )
865	            {
866	                _lastWindowsOcrRetryUtc = DateTime.UtcNow;
867	                TryRecreateWindowsOcrEngine(lang, backend);
868	            }
869	            return;
870	        }
871	
872	        _windowsOcrEngine = new WindowsOcrEngine(lang, _logger);
873	        _activeOcrBackend = backend;
874	        _activeOcrLanguage = lang;
875	        _metrics.OcrBackend = backend;
876	        _logger.LogInformation("OCR backend: Windows.Media.Ocr ({Lang})", lang);
877	    }
