908	    private bool TrySkipOcrViaFrameDifferencing(Bitmap bitmap, OcrOptions currentOptions)
909	    {
910	        if (_options.CurrentValue.BypassOcrCache)
911	            return false;
912	
913	        // When the options object reference changes (meaning IOptionsMonitor created
914	        // a new instance after a config reload), invalidate the cache so new values
915	        // (tolerance, thresholds, etc.) take effect immediately.
916	        if (!ReferenceEquals(_lastOcrOptions, currentOptions))
917	            return false;
918	
919	        var hash = ComputeFastFrameHash(bitmap);
920	        if (hash == 0) return false;
921	        if (hash == _runContext.FrameHash && _lastOcrText.Length > 0)
922	            return true;
923	        _runContext = _runContext with { FrameHash = hash };
924	        return false;
925	    }
