927	    private static long ComputeFastFrameHash(Bitmap bitmap)
928	    {
929	        var rect = new Rectangle(0, 0, bitmap.Width, bitmap.Height);
930	        BitmapData data;
931	        try { data = bitmap.LockBits(rect, ImageLockMode.ReadOnly, bitmap.PixelFormat); }
932	        catch { return 0; }
933	
934	        try
935	        {
936	            var bpp = Image.GetPixelFormatSize(bitmap.PixelFormat) / 8;
937	            if (bpp < 3) return 0;
938	            var stride = Math.Abs(data.Stride);
939	            var rowBytes = new byte[stride];
940	
941	            unchecked
942	            {
943	                long hash = 17;
944	                const int stepX = 8;
945	                const int stepY = 4;
946	                for (var y = 0; y < data.Height; y += stepY)
947	                {
948	                    Marshal.Copy(data.Scan0 + (y * stride), rowBytes, 0, stride);
949	                    for (var x = 0; x < data.Width; x += stepX)
950	                    {
951	                        var idx = x * bpp;
952	                        if (idx + 2 < stride)
953	                            hash = (hash * 31) + rowBytes[idx] + rowBytes[idx + 1] + rowBytes[idx + 2];
954	                    }
955	                }
956	                return hash;
957	            }
958	        }
959	        finally
960	        {
961	            bitmap.UnlockBits(data);
962	        }
963	    }
