1037	    private DebugCaptureContext? TryStartDebugCapture(Bitmap rawImage, OcrCaptureRegion region, string captureMethod)
1038	    {
1039	        var options = _options.CurrentValue;
1040	        // Allow the configured interval, but never more than once per second.
1041	        var minIntervalSeconds = Math.Max(1, options.DebugImageIntervalSeconds);
1042	        var now = DateTimeOffset.UtcNow;
1043	        if (now - _lastDebugImageSavedAtUtc < TimeSpan.FromSeconds(minIntervalSeconds))
1044	            return null;
1045	
1046	        // Only save when the frame content has actually changed (different hash).
1047	        var frameHash = ComputeFastFrameHash(rawImage);
1048	        if (frameHash == _lastDebugFrameHash)
1049	            return null;
1050	        _lastDebugFrameHash = frameHash;
1051	
1052	        _lastDebugImageSavedAtUtc = now;
1053	
1054	        var directory = ResolveDebugImageDirectory(options);
1055	
1056	        try
1057	        {
1058	            _ = Directory.CreateDirectory(directory);
1059	            if (!_logState.HasFlag(OcrLogState.DebugDirectoryLogged))
1060	            {
1061	                _logState |= OcrLogState.DebugDirectoryLogged;
1062	                _logger.LogInformation("OCR debug image output enabled. Directory: {Path}", SanitizePathForLog(Path.GetFullPath(directory)));
1063	            }
1064	
1065	            var rawPath = Path.Combine(directory, "raw.png");
1066	
1067	            OcrCaptureStrategy.SaveBitmapWithOverwrite(rawImage, rawPath);
1068	
1069	            _logger.LogInformation(
1070	                "Saved OCR debug images. Method={Method} Region=X={X} Y={Y} W={W} H={H}",
1071	                captureMethod,
1072	                region.X,
1073	                region.Y,
1074	                region.Width,
1075	                region.Height);
1076	
1077	            return new DebugCaptureContext(directory);
1078	        }
1079	        catch (Exception ex)
1080	        {
1081	            _logger.LogError(ex, "Failed to save OCR debug image to {Dir}: {Context}", directory, ErrorContext.FromException(ex));
