1092	    private static string SanitizePathForLog(string path)
1093	    {
1094	        // Current user's LocalAppData — %LOCALAPPDATA% is always accurate
1095	        var localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
1096	        if (!string.IsNullOrEmpty(localAppData) && path.StartsWith(localAppData, StringComparison.OrdinalIgnoreCase))
1097	            return "%LOCALAPPDATA%" + path[localAppData.Length..];
1098	
1099	        // Current user's profile — %USERPROFILE% is accurate here
1100	        var userProfile = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
1101	        if (!string.IsNullOrEmpty(userProfile) && path.StartsWith(userProfile, StringComparison.OrdinalIgnoreCase))
1102	            return "%USERPROFILE%" + path[userProfile.Length..];
1103	
1104	        // Path under a different user's profile — show relative portion only
1105	        var systemDrive = Path.GetPathRoot(Environment.SystemDirectory);
1106	        var profilesDir = systemDrive is not null
1107	            ? Path.Combine(systemDrive, "Users")
1108	            : @"C:\Users";
1109	        if (path.StartsWith(profilesDir, StringComparison.OrdinalIgnoreCase))
1110	        {
1111	            var afterProfiles = path[(profilesDir.Length + 1)..];
1112	            var firstSep = afterProfiles.IndexOf('\\');
1113	            if (firstSep > 0)
1114	                return afterProfiles[(firstSep + 1)..];
1115	        }
1116	
1117	        return path;
1118	    }
