27	    public static Bitmap KeepBlackAndNeighbors(Bitmap source, ILogger? logger = null)
28	    {
29	        var width = source.Width;
30	        var height = source.Height;
31	        logger?.LogTrace("KeepBlackAndNeighbors: {W}x{H}", width, height);
32	        var rect = new Rectangle(0, 0, width, height);
33	        var srcData = source.LockBits(rect, ImageLockMode.ReadOnly, PixelFormat.Format24bppRgb);
34	        int stride;
35	        byte[] srcBytes;
36	        try
37	        {
38	            stride = srcData.Stride;
39	            var length = Math.Abs(stride) * height;
40	            srcBytes = new byte[length];
41	            Marshal.Copy(srcData.Scan0, srcBytes, 0, length);
42	        }
43	        finally
44	        {
45	            source.UnlockBits(srcData);
46	        }
47	
48	        // Flat 1D byte array for mask: 0=discard, 1=keep. Better cache locality than bool[,].
49	        var keep = new byte[width * height];
50	
51	        // First pass: for each sufficiently dark pixel, mark a neighborhood as kept.
52	        // At 1440p+ the game renders more detail, so use a stricter threshold (13)
53	        // to avoid picking up rune/UI noise as text rows. on 1080p and lower, 15 is fine.
54	        var blackThreshold = width >= 600 ? 13 : 15;
55	        for (var y = 0; y < height; y++)
56	        {
57	            var rowOffset = y * stride;
58	            for (var x = 0; x < width; x++)
59	            {
60	                var idx = rowOffset + (x * 3);
61	                if (srcBytes[idx] > blackThreshold || srcBytes[idx + 1] > blackThreshold || srcBytes[idx + 2] > blackThreshold)
62	                    continue;
63	
64	                var y0 = Math.Max(0, y - 6);
65	                var y1 = Math.Min(height - 1, y + 6);
66	                var x0 = Math.Max(0, x - 6);
67	                var x1 = Math.Min(width - 1, x + 6);
68	                for (var ny = y0; ny <= y1; ny++)
69	                {
70	                    var keepNY = ny * width;
71	                    for (var nx = x0; nx <= x1; nx++)
72	                        keep[keepNY + nx] = 1;
73	                }
74	            }
75	        }
76	
77	        // Second pass: remove bright yellow pixels (the debug overlay's scan bracket
78	        // lines) that survived the neighborhood keep but aren't game content. The
79	        // overlay draws in RGB(255,255,0) at alpha 220 — these high-R, high-G, low-B
80	        // pixels have no equivalent in the game UI (which uses desaturated colors), so
81	        // the filter should be safe.
82	        for (var y = 0; y < height; y++)
83	        {
84	            var srcRow = y * stride;
85	            for (var x = 0; x < width; x++)
86	            {
87	                var si = srcRow + (x * 3);
88	                var b = srcBytes[si];
89	                var g = srcBytes[si + 1];
90	                var r = srcBytes[si + 2];
91	                if (r > 200 && g > 200 && b < 100)
92	                {
93	                    // Bright yellow — overlay scan bracket; exclude from keep mask
94	                    keep[(y * width) + x] = 0;
95	                }
96	            }
97	        }
98	
99	        // Third pass: build output bitmap from masked pixels
100	        var result = new Bitmap(width, height, PixelFormat.Format24bppRgb);
101	        try
102	        {
103	            var dstData = result.LockBits(rect, ImageLockMode.WriteOnly, PixelFormat.Format24bppRgb);
104	            try
105	            {
106	                var dstStride = dstData.Stride;
107	                var dstLength = Math.Abs(dstStride) * height;
108	                var dstBytes = new byte[dstLength];
109	
110	                for (var y = 0; y < height; y++)
111	                {
112	                    var srcRow = y * stride;
113	                    var dstRow = y * dstStride;
114	                    var keepRow = y * width;
115	                    for (var x = 0; x < width; x++)
116	                    {
117	                        var di = dstRow + (x * 3);
118	                        if (keep[keepRow + x] != 0)
119	                        {
120	                            var si = srcRow + (x * 3);
121	                            dstBytes[di] = srcBytes[si];
122	                            dstBytes[di + 1] = srcBytes[si + 1];
123	                            dstBytes[di + 2] = srcBytes[si + 2];
124	                        }
125	                        else
126	                        {
127	                            dstBytes[di] = dstBytes[di + 1] = dstBytes[di + 2] = 255;
128	                        }
129	                    }
130	                }
131	
132	                Marshal.Copy(dstBytes, 0, dstData.Scan0, dstLength);
133	            }
134	            finally
135	            {
136	                result.UnlockBits(dstData);
137	            }
138	
139	            return result;
140	        }
141	        catch
142	        {
143	            result.Dispose();
144	            throw;
145	        }
146	    }
