148	    public static Bitmap PreprocessForOcr(Bitmap source, OcrOptions options, ILogger? logger = null)
149	    {
150	        var threshold = Math.Clamp(options.BinarizationThreshold, 0, 255);
151	        var width = source.Width;
152	        var height = source.Height;
153	        logger?.LogTrace("PreprocessForOcr: {W}x{H} threshold={T}", width, height, threshold);
154	
155	        // Fast grayscale via LockBits (avoids GDI ColorMatrix rendering overhead)
156	        Bitmap? grayscale = new(width, height, PixelFormat.Format24bppRgb);
157	        Bitmap grayscaleSnapshot;
158	        try
159	        {
160	            FastGrayscale(source, grayscale, logger);
161	            grayscaleSnapshot = (Bitmap)grayscale.Clone();
162	        }
163	        catch
164	        {
165	            grayscale.Dispose();
166	            throw;
167	        }
168	
169	        using var grayscaleSnapshotOwner = grayscaleSnapshot;
170	
171	        var rect = new Rectangle(0, 0, width, height);
172	        var data = grayscale.LockBits(rect, ImageLockMode.ReadWrite, PixelFormat.Format24bppRgb);
173	        try
174	        {
175	            var kernelRadius = Math.Clamp(Math.Min(width, height) / 40, 4, 10);
176	            var contrastBias = Math.Clamp((threshold - 100) / 6, 6, 20);
177	
178	            var length = Math.Abs(data.Stride) * data.Height;
179	            var bytes = new byte[length];
180	            Marshal.Copy(data.Scan0, bytes, 0, length);
181	            var grayscalePixels = new byte[width * height];
182	
183	            var absStride = Math.Abs(data.Stride);
184	            for (var y = 0; y < height; y++)
185	            {
186	                var rowOffset = y * absStride;
187	                var grayOffset = y * width;
188	                for (var x = 0; x < width; x++)
189	                {
190	                    grayscalePixels[grayOffset + x] = bytes[rowOffset + (x * 3)];
191	                }
192	            }
193	            logger?.LogTrace("PreprocessForOcr: stride={S} absStride={AS}", data.Stride, absStride);
194	
195	            var integral = BuildIntegralImage(grayscalePixels, width, height);
196	            var binarizedPixels = new byte[width * height];
197	
198	            var sourceRgb = ReadRgbPixels(source);
199	
200	            for (var y = 0; y < height; y++)
201	            {
202	                var rowOffset = y * width;
203	                for (var x = 0; x < width; x++)
204	                {
205	                    var mean = GetLocalMean(integral, width, height, x, y, kernelRadius);
206	                    var luminance = grayscalePixels[rowOffset + x];
207	                    var binarized = luminance + contrastBias < mean ? (byte)0 : (byte)255;
208	                    if (binarized == 0 &&
209	                        options.EnableTextColorFiltering &&
210	                        !IsLikelyTextColor(sourceRgb, rowOffset + x, options))
211	                    {
212	                        binarized = 255;
213	                    }
214	
215	                    binarizedPixels[rowOffset + x] = binarized;
216	                }
217	            }
218	
219	            RemoveIsolatedBlackNoise(binarizedPixels, width, height);
220	
221	            var totalPixels = width * height;
222	            var finalBlackCount = 0;
223	            for (var i = 0; i < binarizedPixels.Length; i++)
224	            {
225	                if (binarizedPixels[i] == 0)
226	                    finalBlackCount++;
227	            }
228	            var blackRatio = totalPixels == 0 ? 1d : (double)finalBlackCount / totalPixels;
229	            if (blackRatio > 0.97d)
230	            {
231	                grayscale.UnlockBits(data);
232	                grayscale.Dispose();
233	                grayscale = null;
234	                return (Bitmap)grayscaleSnapshotOwner.Clone();
235	            }
236	
237	            for (var y = 0; y < height; y++)
238	            {
239	                var rowOffset = y * data.Stride;
240	                var binaryOffset = y * width;
241	                for (var x = 0; x < width; x++)
242	                {
243	                    var index = rowOffset + (x * 3);
244	                    var value = binarizedPixels[binaryOffset + x];
245	                    bytes[index] = value;
246	                    bytes[index + 1] = value;
247	                    bytes[index + 2] = value;
248	                }
249	            }
250	
251	            Marshal.Copy(bytes, 0, data.Scan0, length);
252	            grayscale.UnlockBits(data);
253	            var result = grayscale;
254	            grayscale = null;
255	            return result;
256	        }
257	        finally
258	        {
259	            grayscale?.UnlockBits(data);
260	            grayscale?.Dispose();
261	        }
262	    }
