269	    public static Bitmap UpscaleForOcr(Bitmap source, int scaleFactor)
270	    {
271	        var scale = Math.Clamp(scaleFactor, 1, 6);
272	        if (scale == 1)
273	            return (Bitmap)source.Clone();
274	
275	        var srcW = source.Width;
276	        var srcH = source.Height;
277	        var dstW = srcW * scale;
278	        var dstH = srcH * scale;
279	
280	        var srcRect = new Rectangle(0, 0, srcW, srcH);
281	        var srcData = source.LockBits(srcRect, ImageLockMode.ReadOnly, PixelFormat.Format24bppRgb);
282	        int srcStride;
283	        byte[] srcBytes;
284	        try
285	        {
286	            srcStride = srcData.Stride;
287	            srcBytes = new byte[Math.Abs(srcStride) * srcH];
288	            Marshal.Copy(srcData.Scan0, srcBytes, 0, srcBytes.Length);
289	        }
290	        finally
291	        {
292	            source.UnlockBits(srcData);
293	        }
294	
295	        var upscaled = new Bitmap(dstW, dstH, PixelFormat.Format24bppRgb);
296	        try
297	        {
298	            var dstRect = new Rectangle(0, 0, dstW, dstH);
299	            var dstData = upscaled.LockBits(dstRect, ImageLockMode.WriteOnly, PixelFormat.Format24bppRgb);
300	            try
301	            {
302	                var dstStride = dstData.Stride;
303	                var dstBytes = new byte[Math.Abs(dstStride) * dstH];
304	
305	                // Nearest-neighbor pixel replication (no GDI overhead)
306	                for (var sy = 0; sy < srcH; sy++)
307	                {
308	                    var srcRow = sy * srcStride;
309	                    for (var dy = 0; dy < scale; dy++)
310	                    {
311	                        var dstRow = ((sy * scale) + dy) * dstStride;
312	                        for (var sx = 0; sx < srcW; sx++)
313	                        {
314	                            var b = srcBytes[srcRow + (sx * 3)];
315	                            var g = srcBytes[srcRow + (sx * 3) + 1];
316	                            var r = srcBytes[srcRow + (sx * 3) + 2];
317	                            for (var dx = 0; dx < scale; dx++)
318	                            {
319	                                var di = dstRow + (((sx * scale) + dx) * 3);
320	                                dstBytes[di] = b;
321	                                dstBytes[di + 1] = g;
322	                                dstBytes[di + 2] = r;
323	                            }
324	                        }
325	                    }
326	                }
327	
328	                Marshal.Copy(dstBytes, 0, dstData.Scan0, dstBytes.Length);
329	            }
330	            finally
331	            {
332	                upscaled.UnlockBits(dstData);
333	            }
334	            return upscaled;
335	        }
336	        catch
337	        {
338	            upscaled.Dispose();
339	            throw;
340	        }
341	    }
