414	    {
415	        var width = binarized.Width;
416	        var height = binarized.Height;
417	        var rect = new Rectangle(0, 0, width, height);
418	        var data = binarized.LockBits(rect, ImageLockMode.ReadOnly, PixelFormat.Format24bppRgb);
419	        try
420	        {
