433	    public static Rectangle? FindContentBounds(byte[] bytes, int width, int height, int stride)
434	    {
435	        var minX = width;
436	        var minY = height;
437	        var maxX = 0;
438	        var maxY = 0;
439	
440	        for (var y = 0; y < height; y++)
441	        {
442	            var row = y * stride;
443	            for (var x = 0; x < width; x++)
444	            {
445	                if (bytes[row + (x * 3)] >= 128) continue;
446	                if (x < minX) minX = x;
447	                if (y < minY) minY = y;
448	                if (x > maxX) maxX = x;
449	                if (y > maxY) maxY = y;
450	            }
451	        }
452	
453	        if (minX > maxX) return null;
454	
455	        const int margin = 4;
456	        minX = Math.Max(0, minX - margin);
457	        minY = Math.Max(0, minY - margin);
458	        maxX = Math.Min(width - 1, maxX + margin);
459	        maxY = Math.Min(height - 1, maxY + margin);
460	
461	        var cropW = maxX - minX + 1;
462	        var cropH = maxY - minY + 1;
463	
464	        // Only crop if it saves at least 20% of area
465	        if (cropW * cropH >= width * height * 0.8)
466	            return null;
467	
468	        return new Rectangle(minX, minY, cropW, cropH);
469	    }
