490	    private static void FastGrayscale(Bitmap source, Bitmap dest, ILogger? logger = null)
491	    {
492	        var w = source.Width;
493	        var h = source.Height;
494	        var srcRect = new Rectangle(0, 0, w, h);
495	        // Force Format24bppRgb so stride is always positive and bpp is always 3.
496	        // Using source.PixelFormat is fragile — if a non-24bpp bitmap arrives,
497	        // srcBpp and stride would be wrong, causing out-of-bounds reads.
498	        var srcData = source.LockBits(srcRect, ImageLockMode.ReadOnly, PixelFormat.Format24bppRgb);
499	        try
500	        {
501	            var dstData = dest.LockBits(srcRect, ImageLockMode.WriteOnly, PixelFormat.Format24bppRgb);
502	            try
503	            {
504	                var srcStride = Math.Abs(srcData.Stride);
505	                var dstStride = Math.Abs(dstData.Stride);
506	                var srcBytes = new byte[srcStride * h];
507	                var dstBytes = new byte[dstStride * h];
508	                Marshal.Copy(srcData.Scan0, srcBytes, 0, srcBytes.Length);
509	
510	                logger?.LogTrace(
511	                    "FastGrayscale: {W}x{H} srcStride={S} dstStride={DS}",
512	                    w, h, srcData.Stride, dstData.Stride);
513	
514	                for (var y = 0; y < h; y++)
515	                {
516	                    var srcRow = y * srcStride;
517	                    var dstRow = y * dstStride;
518	                    for (var x = 0; x < w; x++)
519	                    {
520	                        var si = srcRow + (x * 3);
521	                        // ITU-R BT.601 luminance: integer approx of 0.299R + 0.587G + 0.114B
522	                        byte r = srcBytes[si + 2]; // BGR in memory
523	                        byte g = srcBytes[si + 1];
524	                        byte b = srcBytes[si];
525	                        byte lum = (byte)(((77 * r) + (150 * g) + (29 * b)) >> 8);
526	                        var di = dstRow + (x * 3);
527	                        dstBytes[di] = lum;
528	                        dstBytes[di + 1] = lum;
529	                        dstBytes[di + 2] = lum;
530	                    }
531	                }
532	
533	                Marshal.Copy(dstBytes, 0, dstData.Scan0, dstBytes.Length);
534	            }
535	            finally
536	            {
537	                dest.UnlockBits(dstData);
538	            }
539	        }
540	        finally
541	        {
542	            source.UnlockBits(srcData);
543	        }
544	    }
