546	    private static int[] BuildIntegralImage(byte[] grayscalePixels, int width, int height)
547	    {
548	        var integralWidth = width + 1;
549	        var integral = new int[integralWidth * (height + 1)];
550	
551	        for (var y = 1; y <= height; y++)
552	        {
553	            var rowSum = 0;
554	            var grayOffset = (y - 1) * width;
555	            var integralOffset = y * integralWidth;
556	            var previousIntegralOffset = (y - 1) * integralWidth;
557	
558	            for (var x = 1; x <= width; x++)
559	            {
560	                rowSum += grayscalePixels[grayOffset + x - 1];
561	                integral[integralOffset + x] = integral[previousIntegralOffset + x] + rowSum;
562	            }
563	        }
564	
565	        return integral;
566	    }
