568	    private static byte[] ReadRgbPixels(Bitmap bitmap)
569	    {
570	        var rect = new Rectangle(0, 0, bitmap.Width, bitmap.Height);
571	        var data = bitmap.LockBits(rect, ImageLockMode.ReadOnly, PixelFormat.Format24bppRgb);
572	        try
573	        {
574	            var width = data.Width;
575	            var height = data.Height;
576	            var stride = data.Stride;
577	            var rawLength = Math.Abs(stride) * height;
578	            var raw = new byte[rawLength];
579	            Marshal.Copy(data.Scan0, raw, 0, rawLength);
580	
581	            var rgb = new byte[width * height * 3];
582	            for (var y = 0; y < height; y++)
583	            {
584	                var srcRow = y * stride;
585	                var dstRow = y * width * 3;
586	                for (var x = 0; x < width; x++)
587	                {
588	                    var src = srcRow + (x * 3);
589	                    var dst = dstRow + (x * 3);
590	                    rgb[dst] = raw[src + 2];
591	                    rgb[dst + 1] = raw[src + 1];
592	                    rgb[dst + 2] = raw[src];
593	                }
594	            }
595	
596	            return rgb;
597	        }
598	        finally
599	        {
600	            bitmap.UnlockBits(data);
601	        }
602	    }
