604	    private static bool IsLikelyTextColor(byte[] rgbPixels, int pixelIndex, OcrOptions options)
605	    {
606	        var rgbIndex = pixelIndex * 3;
607	        var r = rgbPixels[rgbIndex];
608	        var g = rgbPixels[rgbIndex + 1];
609	        var b = rgbPixels[rgbIndex + 2];
610	
611	        var max = Math.Max(r, Math.Max(g, b));
612	        var min = Math.Min(r, Math.Min(g, b));
613	        var spread = max - min;
614	        var luminance = ((299 * r) + (587 * g) + (114 * b)) / 1000;
615	
616	        if (luminance > options.TextColorMaxLuminance)
617	        {
618	            return false;
619	        }
620	
621	        var dr = r - options.TextColorTargetR;
622	        var dg = g - options.TextColorTargetG;
623	        var db = b - options.TextColorTargetB;
624	        var distanceSquared = (dr * dr) + (dg * dg) + (db * db);
625	        var toleranceSquared = options.TextColorTolerance * options.TextColorTolerance;
626	
627	        if (distanceSquared <= toleranceSquared)
628	        {
629	            return true;
630	        }
631	
632	        return spread <= options.TextColorMaxChannelSpread;
633	    }
634	    private static int GetLocalMean(int[] integral, int width, int height, int x, int y, int radius)
635	    {
636	        var integralWidth = width + 1;
637	
638	        var x0 = Math.Max(0, x - radius);
639	        var y0 = Math.Max(0, y - radius);
640	        var x1 = Math.Min(width - 1, x + radius);
641	        var y1 = Math.Min(height - 1, y + radius);
642	
643	        var area = (x1 - x0 + 1) * (y1 - y0 + 1);
644	
645	        var topLeft = integral[(y0 * integralWidth) + x0];
646	        var topRight = integral[(y0 * integralWidth) + x1 + 1];
647	        var bottomLeft = integral[((y1 + 1) * integralWidth) + x0];
648	        var bottomRight = integral[((y1 + 1) * integralWidth) + x1 + 1];
649	
650	        return (bottomRight - bottomLeft - topRight + topLeft) / Math.Max(1, area);
651	    }
