653	    private static void RemoveIsolatedBlackNoise(byte[] pixels, int width, int height)
654	    {
655	        var source = (byte[])pixels.Clone();
656	
657	        for (var y = 1; y < height - 1; y++)
658	        {
659	            var offset = y * width;
