        // we can see exactly where they land relative to the icon strip above/beside them.
        using var overlay = (Bitmap)raw.Clone();
        using (var g = Graphics.FromImage(overlay))
        using (var pen = new Pen(Color.Lime, 2f))
        using (var pen2 = new Pen(Color.Red, 1f))
        {
            if (crop.HasValue)
                g.DrawRectangle(pen2, crop.Value.X, crop.Value.Y, crop.Value.Width, crop.Value.Height);
            for (var i = 0; i < rowYs.Length; i++)
                g.DrawRectangle(pen, 0, rowYs[i], overlay.Width - 1, rowHeights[i]);
        }
        var outDir = Path.Combine(AppContext.BaseDirectory, "rune-probe-out");
        Directory.CreateDirectory(outDir);
        var outPath = Path.Combine(outDir, "row-bands-overlay.png");
        OcrImagePreprocessor.SavePng(overlay, outPath);
        _output.WriteLine($"Overlay written to: {outPath}");
    }

    private static string? ResolveFixturePath()
    {
        var dir = AppContext.BaseDirectory;
        for (var i = 0; i < 6; i++)
        {
            var candidate = Path.Combine(dir, FixturePath);
            if (File.Exists(candidate)) return candidate;
            dir = Path.GetFullPath(Path.Combine(dir, ".."));
        }
        // Also try relative to repo root when run from `dotnet test` in tests/
        var repoRelative = Path.Combine("tests", FixturePath);
        return File.Exists(repoRelative) ? repoRelative : null;
    }
}

