        {
            var sy0 = dy * srcDim / dstH;
            var sy1 = Math.Max(sy0 + 1, (dy + 1) * srcDim / dstH);
            for (var dx = 0; dx < dstW; dx++)
            {
                var sx0 = dx * srcDim / dstW;
                var sx1 = Math.Max(sx0 + 1, (dx + 1) * srcDim / dstW);

                long sum = 0;
                var n = 0;
                for (var sy = sy0; sy < sy1; sy++)
                {
