// Merge segments separated by a hairline gap (anti-aliased cell border shadow).
var rawMerged = new List<(int Start, int End)>();
foreach (var seg in segments)
{
    if (rawMerged.Count > 0 && seg.Start - rawMerged[^1].End <= 3)
        rawMerged[^1] = (rawMerged[^1].Start, seg.End);
    else
        rawMerged.Add(seg);
}

// Cells are roughly square, so a real cell's width tracks the band height, not an
// absolute pixel constant — the panel visibly shrinks icon size on rows further down
// the list (confirmed on the real 2560x1440 fixture: ~46px cells in the first three
// rows, ~32px in the last three). Drop anything too thin to plausibly be one cell.
var minCellWidth = Math.Max(MinCellPx / 2, (int)(band.Height * 0.5));
var candidates = rawMerged.Where(s => s.End - s.Start + 1 >= minCellWidth).ToList();
if (candidates.Count == 0) return [];

// Two adjacent cells occasionally fuse into one column-ink segment (a bright glyph
// near a shared edge keeps the gap column above threshold). A fused segment is a
// multiple of the row's typical cell width — split it evenly rather than treating it
// as one oversized cell, so a gilded cell hiding inside a fused blob isn't diluted.
var widths = candidates.Select(s => s.End - s.Start + 1).OrderBy(w => w).ToList();
var typicalWidth = widths[widths.Count / 2];

var merged = new List<(int Start, int End)>();
foreach (var (start, end) in candidates)
{
    var segWidth = end - start + 1;
    var pieces = typicalWidth > 0 ? Math.Max(1, (int)Math.Round(segWidth / (double)typicalWidth)) : 1;
    if (pieces <= 1 || segWidth < typicalWidth * 1.4)
    {
        merged.Add((start, end));
        continue;
    }
    var pieceWidth = segWidth / (double)pieces;
    for (var p = 0; p < pieces; p++)
    {
        var pStart = start + (int)Math.Round(p * pieceWidth);
        var pEnd = p == pieces - 1 ? end : start + (int)Math.Round((p + 1) * pieceWidth) - 1;
        merged.Add((pStart, pEnd));
    }
}

