/// <summary>
/// Runs the full pipeline for one text row: locate the icon band above it, segment
/// cells, classify gilded, and hash the survivors. Never throws — a skip predicate
/// firing logs once (via <paramref name="logSkip"/>) and yields no keys for the row.
/// </summary>
public static IReadOnlyList<RuneKey> ExtractRowKeys(
    Bitmap rawBitmap, int rowTextY, int searchTop, ILogger? logger = null)
{
    if (rawBitmap is null) return [];
    var width = rawBitmap.Width;
    var height = rawBitmap.Height;
    var clampedTop = Math.Max(0, Math.Min(searchTop, rowTextY));
    var windowHeight = rowTextY - clampedTop;
    if (windowHeight < MinCellPx)
    {
        logger?.LogDebug("RuneIconFingerprinter: skip row @Y={RowY} — search window {H}px < MinCellPx", rowTextY, windowHeight);
        return [];
    }

    var rect = new Rectangle(0, 0, width, height);
    var data = rawBitmap.LockBits(rect, ImageLockMode.ReadOnly, PixelFormat.Format24bppRgb);
    byte[] rgb;
    int stride;
    try
    {
        stride = data.Stride;
        rgb = new byte[Math.Abs(stride) * height];
        Marshal.Copy(data.Scan0, rgb, 0, rgb.Length);
    }
    finally
    {
        rawBitmap.UnlockBits(data);
    }

    var band = DetectIconBand(rgb, width, stride, clampedTop, rowTextY);
    if (band is null || band.Value.Height < MinCellPx)
    {
        logger?.LogDebug("RuneIconFingerprinter: skip row @Y={RowY} — no icon band found in [{Top},{Bottom})", rowTextY, clampedTop, rowTextY);
        return [];
    }

    var cells = SegmentIconCells(rgb, width, stride, band.Value, clampedTop);
    if (cells.Count == 0) return [];

